_ARTIFACT_OUTPUT_MODES = {
    "spreadsheet_edit",
    "spreadsheet_create",
    "document_create",
    "presentation_create",
}
_CLEAN_WORKSPACE_REQUEST = (
    "Keep the shared company workspace clean: change only the requested target file "
    "and do not leave behind draft scripts or temporary exports."
)
_SPREADSHEET_FINAL_CHECK = (
    "Open and recalculate the exact saved target before finishing, and verify that it "
    "contains no spreadsheet error values."
)

TASKS: tuple[TaskSpec, ...] = tuple(
    replace(
        task,
        prompt=(
            f"{task.prompt.rstrip()}\n\n{_CLEAN_WORKSPACE_REQUEST}"
            f"{' ' + _SPREADSHEET_FINAL_CHECK if task.output_mode in {'spreadsheet_edit', 'spreadsheet_create'} else ''}\n"
        ),
    )
    if task.output_mode in _ARTIFACT_OUTPUT_MODES and task.task_id not in {"task_048", "task_072"}
    else task
    for task in _TASKS
)
